import { Mesh, PlaneGeometry, Group, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, time, fract, sin } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Color } = THREE;

  const group = new Group();

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const inkCol = new Color(inkHex);
  const surfaceCol = new Color(surfaceHex);
  const accentCol = new Color(accentHex);
  const paperCol = new Color(paperHex);

  const inkVec = vec3(inkCol.r, inkCol.g, inkCol.b);
  const surfaceVec = vec3(surfaceCol.r, surfaceCol.g, surfaceCol.b);

  // ---- Backdrop plane with engineered gradient + subtle grain ----
  const backdropW = 2.4;
  const backdropH = 1.6;
  const backdropGeo = new PlaneGeometry(backdropW, backdropH);
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true });

  const gradY = uv().oneMinus().y;
  let colorNode = mix(surfaceVec, inkVec, gradY);

  // Subtle engineered grain via hash
  const grain = fract(sin(uv().x.mul(127.1).add(uv().y.mul(311.7)).add(time.mul(0.3))).mul(43758.5453));
  colorNode = colorNode.add(grain.mul(0.02));

  // Vignette darkening at edges
  const cx = uv().x.sub(0.5);
  const cy = uv().y.sub(0.5);
  const vignette = cx.mul(cx).add(cy.mul(cy)).pow(0.8);
  colorNode = colorNode.mul(vignette.oneMinus().mul(0.35).add(0.65));

  backdropMat.colorNode = colorNode;

  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.z = -0.03;
  group.add(backdrop);

  // ---- Image plane ----
  const planeGeo = new PlaneGeometry(1.7, 1.05);
  const planeMat = new MeshBasicNodeMaterial({ transparent: true });

  const imageUrl = config.imageUrl;
  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  const plane = new Mesh(planeGeo, planeMat);
  plane.position.set(0, 0.1, 0.01);
  group.add(plane);

  // ---- Accent underline ----
  const accentGeo = new PlaneGeometry(0.5, 0.018);
  const accentMat = new MeshBasicNodeMaterial({ transparent: true });
  accentMat.colorNode = vec3(accentCol.r, accentCol.g, accentCol.b);
  const accentLine = new Mesh(accentGeo, accentMat);
  accentLine.position.set(-0.6, -0.45, 0.02);
  group.add(accentLine);

  // ---- Text rendering via fontAtlas ----
  for (const item of items) {
    if (!item.text) continue;
    const role = item.role ?? 'headline';
    const fontSize = item.typography?.fontSize ?? 39;

    const textMesh = ctx.fontAtlas.createText(String(item.text), {
      fontSize: fontSize,
      color: paperHex,
      align: 'left',
      letterSpacingPx: 0,
    });

    textMesh.position.set(-0.82, -0.58, 0.04);
    group.add(textMesh);
  }

  // ---- Entrance animation (weighted-settle) ----
  const timelines = [];

  const tl = gsap.timeline();
  group.scale.set(0.96, 0.96, 0.96);
  group.position.y += 0.0;

  tl.to(group.scale, {
    x: 1.0,
    y: 1.0,
    z: 1.0,
    duration: 0.9,
    ease: 'power4.out',
  });
  tl.from(group.position, {
    y: '+=0.35',
    duration: 0.7,
    ease: 'power3.out',
  }, 0);
  tl.from(backdropMat, {
    opacity: 0,
    duration: 0.6,
    ease: 'power2.out',
  }, 0);
  tl.from(planeMat, {
    opacity: 0,
    duration: 0.6,
    ease: 'power2.out',
  }, 0.05);

  timelines.push(tl);

  // ---- Handlers (none — static element) ----
  group.userData.handlers = {};

  // ---- Cleanup ----
  group.userData.cleanup = () => {
    timelines.forEach((t) => t.kill());
    backdropGeo.dispose();
    backdropMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();
    accentGeo.dispose();
    accentMat.dispose();
  };

  return group;
}
